'use strict';
const paths={pause:'M8 5v14M16 5v14',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6l1.5 1.5m9.8 9.8 1.5 1.5m0-12.8-1.5 1.5M7.1 16.9l-1.5 1.5M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',wind:'M3 8h12a3 3 0 1 0-3-3M3 12h16a3 3 0 1 1-3 3M3 16h6a3 3 0 1 1-3 3',cup:'M5 8h12v8a4 4 0 0 1-4 4H9a4 4 0 0 1-4-4V8Zm12 1h2a3 3 0 0 1 0 6h-2M8 3v2m5-2v2',move:'M12 8a2 2 0 1 0 0-4 2 2 0 0 0 0 4ZM5 11l7-1 7 1m-7-1v6m0 0-4 5m4-5 4 5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Zm13 0a3 3 0 1 1-6 0 3 3 0 0 1 6 0',moon:'M20 15.5A9 9 0 0 1 8.5 4 9 9 0 1 0 20 15.5Z',shield:'M12 3 4 6v6c0 5 8 9 8 9s8-4 8-9V6l-8-3Zm-4 9 3 3 5-6',sliders:'M4 7h16M4 17h16M8 4v6m8 4v6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l3 2',check:'m5 12 4 4L19 6',book:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4V4Zm8 2v15',edit:'m14 5 5 5M4 20l5-1L21 7l-5-5L4 14v6Z',stop:'M5 5h14v14H5z',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z'};
const icon=(name)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.pause}"/></svg>`;
const activities=[{id:'air',title:'A change of scenery',sub:'Look outside. Let your mind wander.',icon:'sun',instruction:'Find a window or step outside, if it feels comfortable. There’s nothing you need to notice or achieve.'},{id:'stretch',title:'A little movement',sub:'Stretch, stroll, or loosen your shoulders.',icon:'move',instruction:'Move in whatever way feels comfortable for you. A small stretch, a short walk, or simply changing position is enough.'},{id:'drink',title:'Something to sip',sub:'Get some water. Make a cup of tea.',icon:'cup',instruction:'Choose a drink you enjoy. You can leave your device here and take your time with it.'},{id:'quiet',title:'A quiet moment',sub:'Sit back. Do absolutely nothing.',icon:'wind',instruction:'Make yourself comfortable. Let your eyes rest wherever you like. You don’t need to follow an exercise.'}];
const state={view:'choose',mood:'',activity:'air',minutes:5,checkin:true,startAt:null,deadline:null,remaining:null,paused:false,feeling:'',outcome:'',note:''};
const main=document.querySelector('#main'); const settings=document.querySelector('#settings');let toastTimer;
function steps(n){return `<nav class="steps" aria-label="Break progress">${['Choose your break','Take your time','Check in'].map((x,i)=>`${i?'<span class="step-line" aria-hidden="true"></span>':''}<span class="step ${i===n?'active':''}" ${i===n?'aria-current="step"':''}><span class="step-number">${i<n?'✓':i+1}</span>${x}</span>`).join('')}</nav>`;}
function escapeText(x){return x.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function activity(){return activities.find(a=>a.id===state.activity)||activities[3];}
function render(focus=true){
 if(state.view==='choose')main.innerHTML=`${steps(0)}<h2>What would feel good right now?</h2><p class="intro">A small pause, on your terms. There’s no right way to rest.</p><div class="section-label">How are you arriving? <span class="optional">Optional</span></div><div class="moods" role="group" aria-label="How you feel">${[['Tired','moon'],['Restless','wind'],['Overwhelmed','spark'],['Just need a pause','pause']].map(([x,i])=>`<button class="pill" data-mood="${x}" aria-pressed="${state.mood===x}">${icon(i)}${x}</button>`).join('')}</div><div class="section-label">Make a little room for yourself</div><div class="options" role="group" aria-label="Break activities">${activities.map(a=>`<button class="option" data-activity="${a.id}" aria-pressed="${state.activity===a.id}"><span class="tile-icon">${icon(a.icon)}</span><span><strong>${a.title}</strong><small>${a.sub}</small></span><span class="selection-dot" aria-hidden="true"></span></button>`).join('')}</div><button class="quiet no-plan" data-action="no-plan">I’d rather take a break without a plan</button><div class="break-controls"><div><div class="section-label">A little time for you</div><div class="durations" role="group" aria-label="Break length">${[3,5,10,0].map(x=>`<button class="time-choice" data-minutes="${x}" aria-pressed="${state.minutes===x}">${x?x+' min':'No timer'}</button>`).join('')}</div></div><label class="switch-row"><span><strong>A gentle check-in</strong><small>${state.minutes?'An invitation, never an alarm.':'Choose a time to enable a check-in.'}</small></span><input type="checkbox" role="switch" id="checkin" ${state.checkin&&state.minutes?'checked':''} ${!state.minutes?'disabled':''}></label></div><div class="start-row"><button class="primary" data-action="start">${icon('pause')} Take my break</button><p>Your device stays available.<br>You can extend, change, or stop at any time.</p></div>`;
 if(state.view==='rest')main.innerHTML=`${steps(1)}<div class="center-stage"><span class="rest-tag">${icon(activity().icon)} ${state.activity==='none'?'A break without a plan':activity().title}</span><h2>This time is yours.</h2><p class="intro">You can put this screen down now.</p><div class="rest-visual"><div class="rest-core">${icon(state.paused?'pause':activity().icon)}<strong id="time-display"></strong><span id="time-label"></span></div></div><p class="rest-description">${state.activity==='none'?'You don’t need an activity or a reason. Do whatever feels restful to you.':activity().instruction}</p><p class="subtle-note">${state.checkin&&state.minutes?'A quiet check-in will appear here. You don’t need to watch for it.':'No check-ins. Stay for as long as you like.'}</p><div class="button-group"><button class="secondary" data-action="extend">Take 5 more minutes</button><button class="primary" data-action="reflect">Check in with myself</button></div><div class="text-actions"><button class="quiet" data-action="pause">${state.paused?'Resume the timer':'Pause the timer'}</button><button class="quiet" data-action="change">Choose a different break</button><button class="quiet" data-action="off">Turn support off</button></div>${state.checkin&&state.minutes?'<button class="demo-button" data-action="demo">Prototype · preview the check-in</button>':''}</div>`;
 if(state.view==='reflect')main.innerHTML=`${steps(2)}<div class="center-stage"><span class="rest-tag">${icon('sun')} A moment to notice</span><h2>No rush. How are you?</h2><p class="intro">${state.outcome==='timed'?'The time you chose has passed. A longer break is okay.':'You get to decide what happens next.'}</p><div class="checkin-box"><strong>Did that feel like the rest you needed?</strong><p>No score, no right answer. This reflection is optional.</p><div class="feeling-options" role="group" aria-label="How the break felt">${['A little restored','About the same','I need more rest'].map(x=>`<button class="pill" data-feeling="${x}" aria-pressed="${state.feeling===x}">${x}</button>`).join('')}</div></div><div class="section-label">What feels right next?</div><div class="choice-list">${[['more','moon','Keep resting','Give yourself more time.'],['return','book','Return to my study','When you feel ready.'],['plan','edit','Change my plan','Something else may matter more now.'],['end','stop','Finish studying for now','You’re allowed to call it a day.']].map(([action,i,t,s])=>`<button class="next-choice" data-action="${action}">${icon(i)}<span class="next-content"><strong>${t}</strong><small>${s}</small></span></button>`).join('')}</div><button class="quiet no-plan" data-action="dismiss">Skip this check-in and keep resting</button></div>`;
 if(state.view==='plan')main.innerHTML=`${steps(2)}<div class="center-stage"><span class="rest-tag">${icon('edit')} A change of direction</span><h2>Your plan can change.</h2><p class="intro">What would you like to make space for instead?</p><label for="new-plan" class="section-label">A note for yourself <span class="optional">Optional · only in this tab</span></label><textarea id="new-plan" maxlength="500" placeholder="Maybe a different task, lunch, or more time for myself…">${escapeText(state.note)}</textarea><div class="button-group"><button class="secondary" data-action="back-reflect">Go back</button><button class="primary" data-action="save-plan">Go with this plan</button></div><button class="quiet no-plan" data-action="skip-plan">Continue without a note</button></div>`;
 if(state.view==='done'){const copy={return:['At your own pace.','Your study is there when you’re ready. You can close this page and return in your own time.'],end:['Enough for now.','You’ve chosen to finish studying. There’s nothing else to complete here.'],plan:['Room for a new direction.','You’ve chosen what feels right for you now. You don’t need to justify the change.']};let [t,p]=copy[state.outcome]||copy.end;main.innerHTML=`<div class="center-stage"><div class="success-mark">${icon('check')}</div><h2>${t}</h2><p class="intro">${p}</p>${state.outcome==='plan'&&state.note?`<div class="checkin-box"><span class="eyebrow">YOUR NEXT INTENTION</span><p>${escapeText(state.note)}</p></div>`:''}<p class="subtle-note">This tab keeps no history. Reloading clears your choices.</p><button class="secondary" data-action="restart">Take another break</button></div>`;}
 if(state.view==='off')main.innerHTML=`<div class="center-stage"><div class="success-mark">${icon('moon')}</div><h2>Space, without the support.</h2><p class="intro">Check-ins and the timer are off.<br>You can keep resting or close this page.</p><p class="subtle-note">Nothing to explain. Come back only if it helps.</p><button class="secondary" data-action="restart">Choose a new break</button></div>`;
 document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));updateClock(); if(focus)main.focus({preventScroll:true});
}
function notify(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,3500);}
function startBreak(){state.view='rest';state.startAt=Date.now();state.deadline=state.minutes?Date.now()+state.minutes*60000:null;state.remaining=null;state.paused=false;state.feeling='';state.outcome='';render();}
function checkIn(timed=false){state.view='reflect';state.outcome=timed?'timed':'';state.deadline=null;state.paused=false;render();}
function supportOff(){state.view='off';state.deadline=null;state.startAt=null;state.checkin=false;state.paused=false;settings.close();render();}
function updateClock(){if(state.view!=='rest')return;const el=document.querySelector('#time-display'),label=document.querySelector('#time-label');if(!el)return;if(!state.minutes){el.textContent='Just be.';label.textContent='No timer';return;}const secs=state.paused?Math.ceil((state.remaining||0)/1000):Math.max(0,Math.ceil(((state.deadline||Date.now())-Date.now())/1000));el.textContent=state.paused?'Paused':`${Math.floor(secs/60)}:${String(secs%60).padStart(2,'0')}`;label.textContent=state.paused?'Take your time':state.checkin?'until your check-in':secs?'your chosen time':'stay as long as you like';if(!state.paused&&state.deadline&&Date.now()>=state.deadline&&state.checkin)checkIn(true);}
function action(name){switch(name){case'start':startBreak();break;case'no-plan':state.activity='none';startBreak();break;case'reflect':checkIn();break;case'demo':checkIn(true);break;case'extend':if(state.minutes){if(state.paused)state.remaining+=300000;else state.deadline=Math.max(Date.now(),state.deadline||0)+300000;updateClock();notify('Five more minutes. Take the time you need.');}else notify('Your break is already open-ended. Take all the time you need.');break;case'pause':if(!state.minutes){notify('There’s no timer to pause. Your break is open-ended.');break;}if(state.paused){state.deadline=Date.now()+state.remaining;state.paused=false;}else{state.remaining=Math.max(0,state.deadline-Date.now());state.paused=true;}render();break;case'change':state.deadline=null;state.view='choose';render();break;case'off':supportOff();break;case'more':state.minutes=5;startBreak();notify('More time for you.');break;case'dismiss':state.minutes=0;startBreak();notify('Check-in dismissed. No more reminders for this break.');break;case'return':case'end':state.outcome=name;state.view='done';state.deadline=null;render();break;case'plan':state.view='plan';render();break;case'back-reflect':state.view='reflect';render();break;case'save-plan':case'skip-plan':if(name==='skip-plan')state.note='';state.outcome='plan';state.view='done';render();break;case'restart':state.view='choose';state.mood='';state.feeling='';state.note='';state.minutes=5;state.activity='air';state.deadline=null;render();break;}}
main.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;if(b.dataset.action)action(b.dataset.action);if(b.dataset.mood){state.mood=state.mood===b.dataset.mood?'':b.dataset.mood;main.querySelectorAll('[data-mood]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.mood===state.mood));}if(b.dataset.activity){state.activity=b.dataset.activity;main.querySelectorAll('[data-activity]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.activity===state.activity));}if(b.dataset.minutes!==undefined){state.minutes=Number(b.dataset.minutes);main.querySelectorAll('[data-minutes]').forEach(x=>x.setAttribute('aria-pressed',Number(x.dataset.minutes)===state.minutes));const c=main.querySelector('#checkin');c.disabled=!state.minutes;c.checked=!!state.minutes&&state.checkin;c.closest('label').querySelector('small').textContent=state.minutes?'An invitation, never an alarm.':'Choose a time to enable a check-in.';}if(b.dataset.feeling){state.feeling=b.dataset.feeling;main.querySelectorAll('[data-feeling]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.feeling===state.feeling));}});
main.addEventListener('change',event=>{if(event.target.id==='checkin')state.checkin=event.target.checked;});main.addEventListener('input',event=>{if(event.target.id==='new-plan')state.note=event.target.value;});
document.querySelector('#settings-open').addEventListener('click',()=>{document.querySelector('#global-checkin').checked=state.checkin;settings.showModal();});document.querySelector('#settings-close').addEventListener('click',()=>settings.close());document.querySelector('#support-off').addEventListener('click',supportOff);document.querySelector('#global-checkin').addEventListener('change',event=>{state.checkin=event.target.checked;if(state.view==='rest'&&state.checkin&&state.minutes&&!state.paused&&state.deadline<=Date.now())state.deadline=Date.now()+state.minutes*60000;render(false);});
setInterval(updateClock,500);document.addEventListener('visibilitychange',()=>{if(!document.hidden)updateClock();});render(false);
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'get_break_state',description:'Read the current break choices and screen. Does not start or change a break.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({screen:state.view,activity:state.activity,minutes:state.minutes,checkin:state.checkin,paused:state.paused})})).catch(()=>{});}catch{}}
